CREATE TABLE public.parametres_site (etablissement_id uuid PRIMARY KEY REFERENCES public.etablissements(id), nom_organisation text NOT NULL DEFAULT 'SYGMA', logo_path text, inactivite_minutes integer NOT NULL DEFAULT 30 CHECK(inactivite_minutes BETWEEN 5 AND 480), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.parametres_site TO authenticated;
GRANT ALL ON public.parametres_site TO service_role;
ALTER TABLE public.parametres_site ENABLE ROW LEVEL SECURITY;
CREATE POLICY site_settings_read ON public.parametres_site FOR SELECT TO authenticated USING(public.user_in_etablissement(auth.uid(),etablissement_id));
CREATE POLICY site_settings_insert ON public.parametres_site FOR INSERT TO authenticated WITH CHECK(public.has_role_in_etablissement(etablissement_id,'super_admin'));
CREATE POLICY site_settings_update ON public.parametres_site FOR UPDATE TO authenticated USING(public.has_role_in_etablissement(etablissement_id,'super_admin')) WITH CHECK(public.has_role_in_etablissement(etablissement_id,'super_admin'));
INSERT INTO public.parametres_site(etablissement_id,nom_organisation) SELECT e.id,coalesce((SELECT nom_organisation FROM public.parametres_organisation WHERE id=1),'SYGMA') FROM public.etablissements e;
COMMENT ON TABLE public.parametres_organisation IS 'DEPRECATED: replaced by parametres_site; legacy logos remain private';
REVOKE ALL ON public.parametres_organisation FROM anon,authenticated;
CREATE TABLE public.notifications_site (etablissement_id uuid NOT NULL REFERENCES public.etablissements(id), evenement text NOT NULL, libelle text NOT NULL, actif boolean NOT NULL DEFAULT false, destinataires text NOT NULL DEFAULT '', sujet text NOT NULL DEFAULT '', contenu text NOT NULL DEFAULT '', PRIMARY KEY(etablissement_id,evenement));
GRANT SELECT,INSERT,UPDATE ON public.notifications_site TO authenticated;
GRANT ALL ON public.notifications_site TO service_role;
ALTER TABLE public.notifications_site ENABLE ROW LEVEL SECURITY;
CREATE POLICY notif_read ON public.notifications_site FOR SELECT TO authenticated USING(public.has_role_in_etablissement(etablissement_id,'super_admin'));
CREATE POLICY notif_insert ON public.notifications_site FOR INSERT TO authenticated WITH CHECK(public.has_role_in_etablissement(etablissement_id,'super_admin'));
CREATE POLICY notif_update ON public.notifications_site FOR UPDATE TO authenticated USING(public.has_role_in_etablissement(etablissement_id,'super_admin')) WITH CHECK(public.has_role_in_etablissement(etablissement_id,'super_admin'));
INSERT INTO public.notifications_site SELECT e.id,n.evenement,n.libelle,n.actif,n.destinataires,n.sujet,n.contenu FROM public.etablissements e CROSS JOIN public.parametres_notifications n;
COMMENT ON TABLE public.parametres_notifications IS 'DEPRECATED: replaced by notifications_site';
REVOKE ALL ON public.parametres_notifications FROM anon,authenticated;
ALTER TABLE public.checklist_operations ADD COLUMN etablissement_id uuid REFERENCES public.etablissements(id);
INSERT INTO public.checklist_operations(phase,categorie_equipement,libelle,ordre,actif,etablissement_id) SELECT r.phase,r.categorie_equipement,r.libelle,r.ordre,r.actif,e.id FROM public.checklist_operations r CROSS JOIN public.etablissements e WHERE r.etablissement_id IS NULL;
ALTER TABLE public.referentiels ADD COLUMN etablissement_id uuid REFERENCES public.etablissements(id);
ALTER TABLE public.referentiels DROP CONSTRAINT referentiels_type_libelle_key;
ALTER TABLE public.referentiels ADD CONSTRAINT ref_site_unique UNIQUE(etablissement_id,type,libelle);
INSERT INTO public.referentiels(type,libelle,actif,ordre,etablissement_id) SELECT r.type,r.libelle,r.actif,r.ordre,e.id FROM public.referentiels r CROSS JOIN public.etablissements e WHERE r.etablissement_id IS NULL;
ALTER TABLE public.libelles_statuts ADD COLUMN etablissement_id uuid REFERENCES public.etablissements(id);
ALTER TABLE public.libelles_statuts DROP CONSTRAINT libelles_statuts_domaine_code_key;
ALTER TABLE public.libelles_statuts ADD CONSTRAINT labels_site_unique UNIQUE(etablissement_id,domaine,code);
INSERT INTO public.libelles_statuts(domaine,code,libelle,couleur,etablissement_id) SELECT r.domaine,r.code,r.libelle,r.couleur,e.id FROM public.libelles_statuts r CROSS JOIN public.etablissements e WHERE r.etablissement_id IS NULL;
DO $$ DECLARE t text; p record; BEGIN FOREACH t IN ARRAY ARRAY['checklist_operations','referentiels','libelles_statuts'] LOOP FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('CREATE POLICY site_read ON public.%I FOR SELECT TO authenticated USING(public.user_in_etablissement(auth.uid(),etablissement_id))',t); EXECUTE format('CREATE POLICY site_write ON public.%I FOR ALL TO authenticated USING(public.has_any_role_in(auth.uid(),etablissement_id,ARRAY[''super_admin'',''responsable_maintenance'']::public.app_role[])) WITH CHECK(public.has_any_role_in(auth.uid(),etablissement_id,ARRAY[''super_admin'',''responsable_maintenance'']::public.app_role[]))',t); EXECUTE format('CREATE TRIGGER lock_site BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.lock_etablissement_id()',t); END LOOP; END $$;
CREATE POLICY historical_checklist_read ON public.checklist_operations FOR SELECT TO authenticated USING(etablissement_id IS NULL AND (EXISTS(SELECT 1 FROM public.rapport_operations_realisees r WHERE r.operation_id=checklist_operations.id) OR EXISTS(SELECT 1 FROM public.visites_quotidiennes_operations v WHERE v.operation_id=checklist_operations.id)));
DROP POLICY IF EXISTS roles_manage_admin ON public.user_roles;
REVOKE INSERT,UPDATE,DELETE ON public.user_roles FROM authenticated,anon;
DROP POLICY IF EXISTS ue_manage_admin ON public.utilisateur_etablissements;
REVOKE INSERT,UPDATE,DELETE ON public.utilisateur_etablissements FROM authenticated,anon;
DROP POLICY IF EXISTS profil_delete_admin ON public.profils_utilisateurs;
DROP POLICY IF EXISTS profil_insert_self_or_admin ON public.profils_utilisateurs;
DROP POLICY IF EXISTS profil_update_self_or_admin ON public.profils_utilisateurs;
CREATE POLICY profile_insert_self ON public.profils_utilisateurs FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY profile_update_self ON public.profils_utilisateurs FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY intervention_site_boundary ON public.interventions AS RESTRICTIVE FOR ALL TO authenticated USING(public.user_in_etablissement(auth.uid(),etablissement_id)) WITH CHECK(public.user_in_etablissement(auth.uid(),etablissement_id));
CREATE POLICY prestataire_site_boundary ON public.prestataires AS RESTRICTIVE FOR ALL TO authenticated USING(public.user_in_etablissement(auth.uid(),etablissement_id)) WITH CHECK(public.user_in_etablissement(auth.uid(),etablissement_id));
CREATE OR REPLACE FUNCTION public.is_intervention_technicien(_user_id uuid,_intervention_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.interventions i WHERE i.id=_intervention_id AND public.user_in_etablissement(_user_id,i.etablissement_id) AND (EXISTS(SELECT 1 FROM public.intervention_techniciens t WHERE t.intervention_id=i.id AND t.technicien_id=_user_id) OR EXISTS(SELECT 1 FROM public.prestataires p WHERE p.id=i.prestataire_id AND p.user_id=_user_id AND p.etablissement_id=i.etablissement_id AND p.actif))); $$;
CREATE OR REPLACE FUNCTION public.can_edit_visite(_user_id uuid,_visite_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.visites_quotidiennes v WHERE v.id=_visite_id AND public.user_in_etablissement(_user_id,v.etablissement_id) AND v.signature_at IS NULL AND (v.technicien_id=_user_id OR public.can_manage_intervention(_user_id,v.etablissement_id))); $$;
CREATE OR REPLACE FUNCTION public.can_view_demande(_user_id uuid,_demande_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.demandes_intervention d WHERE d.id=_demande_id AND public.user_in_etablissement(_user_id,d.etablissement_id) AND (d.demandeur_id=_user_id OR d.technicien_id=_user_id OR public.can_manage_intervention(_user_id,d.etablissement_id) OR EXISTS(SELECT 1 FROM public.prestataires p WHERE p.id=d.prestataire_id AND p.user_id=_user_id AND p.etablissement_id=d.etablissement_id AND p.actif))); $$;
DROP POLICY IF EXISTS branding_read ON storage.objects;
DROP POLICY IF EXISTS branding_insert ON storage.objects;
DROP POLICY IF EXISTS branding_update ON storage.objects;
DROP POLICY IF EXISTS branding_delete ON storage.objects;
CREATE POLICY branding_site_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='branding' AND EXISTS(SELECT 1 FROM public.parametres_site s WHERE s.logo_path=objects.name AND public.user_in_etablissement(auth.uid(),s.etablissement_id)));
CREATE POLICY branding_site_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='branding' AND EXISTS(SELECT 1 FROM public.etablissements e WHERE e.id::text=split_part(objects.name,'/',1) AND public.has_role_in_etablissement(e.id,'super_admin')));
CREATE POLICY branding_site_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='branding' AND owner=auth.uid() AND EXISTS(SELECT 1 FROM public.etablissements e WHERE e.id::text=split_part(objects.name,'/',1) AND public.has_role_in_etablissement(e.id,'super_admin')));
DROP POLICY IF EXISTS commandes_files_read ON storage.objects;
CREATE POLICY commandes_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='commandes' AND EXISTS(SELECT 1 FROM public.commandes_achat c WHERE objects.name=ANY(c.pieces_jointes) AND public.can_manage_stock(auth.uid(),c.etablissement_id)));
ALTER TABLE public.audit_logs ADD COLUMN etablissement_id uuid REFERENCES public.etablissements(id);
DROP POLICY IF EXISTS audit_select_super ON public.audit_logs;
CREATE POLICY audit_select_site ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role_in_etablissement(etablissement_id,'super_admin') OR etablissement_id IS NULL AND (details ? 'affectations' OR details ? 'etablissements') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(details->'affectations','[]'::jsonb)) a WHERE NOT public.has_role_in_etablissement((a->>'etablissement_id')::uuid,'super_admin')) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(details->'etablissements','[]'::jsonb)) s WHERE NOT public.has_role_in_etablissement(s::uuid,'super_admin')) AND (jsonb_array_length(coalesce(details->'affectations','[]'::jsonb))>0 OR jsonb_array_length(coalesce(details->'etablissements','[]'::jsonb))>0));
CREATE OR REPLACE FUNCTION public.log_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rec jsonb; site uuid; BEGIN rec:=to_jsonb(coalesce(NEW,OLD)); site:=nullif(rec->>'etablissement_id','')::uuid; INSERT INTO public.audit_logs(user_id,action,table_name,record_id,details,etablissement_id) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,rec->>'id',jsonb_build_object('champs_modifies',CASE WHEN TG_OP='UPDATE' THEN (SELECT jsonb_agg(n.key) FROM jsonb_each(to_jsonb(NEW)) n WHERE n.value IS DISTINCT FROM to_jsonb(OLD)->n.key) ELSE '[]'::jsonb END),site); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER audit_settings AFTER INSERT OR UPDATE ON public.parametres_site FOR EACH ROW EXECUTE FUNCTION public.log_audit();
CREATE TRIGGER lock_settings_site BEFORE UPDATE ON public.parametres_site FOR EACH ROW EXECUTE FUNCTION public.lock_etablissement_id();
CREATE TRIGGER lock_notifications_site BEFORE UPDATE ON public.notifications_site FOR EACH ROW EXECUTE FUNCTION public.lock_etablissement_id();
CREATE OR REPLACE FUNCTION public.validate_record_site() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rec jsonb:=to_jsonb(NEW); site uuid; target uuid; k text; t text; BEGIN site:=nullif(rec->>'etablissement_id','')::uuid; IF site IS NULL THEN IF TG_TABLE_NAME='commandes_achat_lignes' THEN SELECT etablissement_id INTO site FROM public.commandes_achat WHERE id=NEW.commande_id; ELSIF TG_TABLE_NAME='demandes_sortie_lignes' THEN SELECT etablissement_id INTO site FROM public.demandes_sortie_pieces WHERE id=NEW.demande_id; ELSIF TG_TABLE_NAME IN ('stock_mouvements','stock_seuils') THEN SELECT etablissement_id INTO site FROM public.magasins WHERE id=NEW.magasin_id; ELSIF TG_TABLE_NAME='plan_echeances' THEN SELECT etablissement_id INTO site FROM public.plans_preventifs WHERE id=NEW.plan_id; END IF; END IF; FOREACH k IN ARRAY ARRAY['equipement_id','magasin_id','piece_id','intervention_id','prestataire_id','plan_id','demande_id'] LOOP IF nullif(rec->>k,'') IS NULL THEN CONTINUE; END IF; t:=CASE k WHEN 'equipement_id' THEN 'equipements' WHEN 'magasin_id' THEN 'magasins' WHEN 'piece_id' THEN 'pieces' WHEN 'intervention_id' THEN 'interventions' WHEN 'prestataire_id' THEN 'prestataires' WHEN 'plan_id' THEN 'plans_preventifs' WHEN 'demande_id' THEN CASE WHEN TG_TABLE_NAME IN ('bons_sortie','demandes_sortie_lignes') THEN 'demandes_sortie_pieces' ELSE 'demandes_intervention' END END; EXECUTE format('SELECT etablissement_id FROM public.%I WHERE id=$1',t) INTO target USING (rec->>k)::uuid; IF site IS NULL OR target IS DISTINCT FROM site THEN RAISE EXCEPTION 'Les éléments liés doivent appartenir au même établissement'; END IF; END LOOP; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['interventions','demandes_intervention','demandes_sortie_pieces','bons_sortie','commandes_achat','commandes_achat_lignes','demandes_sortie_lignes','stock_mouvements','stock_seuils','plans_preventifs','plan_echeances','visites_quotidiennes'] LOOP EXECUTE format('CREATE TRIGGER validate_site_links BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_record_site()',t); END LOOP; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.set_user_site_access(uuid,jsonb)'::regprocedure) INTO def; def:=replace(def,'IF caller IS NULL THEN','IF caller IS NULL OR auth.role() <> ''authenticated'' THEN'); EXECUTE def; END $$;
REVOKE ALL ON FUNCTION public.set_user_site_access(uuid,jsonb) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.set_user_site_access(uuid,jsonb) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.generer_interventions_preventives()'::regprocedure) INTO def; def:=replace(def,'WHERE actif LOOP','WHERE actif AND ((auth.uid() IS NOT NULL AND public.can_manage_intervention(auth.uid(),etablissement_id)) OR (auth.uid() IS NULL AND session_user IN (''postgres'',''supabase_admin''))) LOOP'); EXECUTE def; END $$;
REVOKE ALL ON FUNCTION public.generer_interventions_preventives() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.generer_interventions_preventives() TO authenticated,service_role;